import{_ as s,o as n,c as i,a3 as a}from"./chunks/framework.DAnVGsli.js";const c=JSON.parse('{"title":"Werkzeuge","description":"","frontmatter":{},"headers":[],"relativePath":"werkzeuge.md","filePath":"werkzeuge.md"}'),t={name:"werkzeuge.md"};function l(r,e,d,o,h,u){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="werkzeuge" tabindex="-1">Werkzeuge <a class="header-anchor" href="#werkzeuge" aria-label="Permalink to &quot;Werkzeuge&quot;">​</a></h1><p>Diese Seite stellt Programme vor, die du außerhalb von Java brauchst. Bisher ist das eines: <strong><code>cloudflared</code></strong>, das deinen Rechner für Telegram per HTTPS erreichbar macht.</p><h2 id="cloudflared-eine-offentliche-https-adresse-fur-deinen-rechner" tabindex="-1">cloudflared: eine öffentliche HTTPS-Adresse für deinen Rechner <a class="header-anchor" href="#cloudflared-eine-offentliche-https-adresse-fur-deinen-rechner" aria-label="Permalink to &quot;cloudflared: eine öffentliche HTTPS-Adresse für deinen Rechner&quot;">​</a></h2><h3 id="wozu-brauchst-du-das" tabindex="-1">Wozu brauchst du das? <a class="header-anchor" href="#wozu-brauchst-du-das" aria-label="Permalink to &quot;Wozu brauchst du das?&quot;">​</a></h3><p>Zwei Teile dieses Kurses verlangen eine Adresse, die Telegram aus dem Internet aufrufen kann:</p><ul><li><strong>Webhooks</strong> (<a href="/learn_telegram/lektionen/06-webhooks.html">Lektion 6</a>): Telegram schickt Updates an eine URL. Dabei ist das Ausprobieren optional.</li><li><strong>Mini Apps</strong> (<a href="/learn_telegram/lektionen/11-mini-apps.html">Lektion 11</a>): Der Telegram-Client lädt deine Webseite von einer URL. Hier ist der Live-Lauf Pflicht.</li></ul><p>Beides geht nur über <strong>HTTPS</strong>. Dein Rechner steht aber meist hinter einem Router und einer Firewall, hat keine feste öffentliche Adresse und kein Zertifikat. Du könntest einen Server mit Domain mieten oder den Router einrichten. Für das Lernen ist das zu viel Aufwand.</p><h3 id="was-macht-cloudflared" tabindex="-1">Was macht cloudflared? <a class="header-anchor" href="#was-macht-cloudflared" aria-label="Permalink to &quot;Was macht cloudflared?&quot;">​</a></h3><p><code>cloudflared</code> ist ein kleines Programm von Cloudflare, die Software für den Dienst <strong>Cloudflare Tunnel</strong>. Es läuft auf deinem Rechner und baut von dort eine <strong>ausgehende</strong> Verbindung zum Netz von Cloudflare auf. Cloudflare nimmt Anfragen unter einer öffentlichen HTTPS-Adresse entgegen und reicht sie durch diese Verbindung an einen Port auf deinem Rechner weiter. Weil die Verbindung von innen nach außen aufgebaut wird, musst du an Router und Firewall nichts freigeben.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Telegram-App oder Telegram-Server</span></span>
<span class="line"><span>        |  HTTPS</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>https://&lt;zufall&gt;.trycloudflare.com      (Cloudflare, nimmt die Anfragen an)</span></span>
<span class="line"><span>        |  durch die Verbindung, die cloudflared von deinem Rechner aufgebaut hat</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>cloudflared  --&gt;  http://localhost:8080   (dein Java-Programm)</span></span></code></pre></div><p>Dein Java-Programm spricht nur gewöhnliches HTTP auf <code>localhost</code>. Das HTTPS endet bei Cloudflare, so wie bei einem Reverse Proxy.</p><h3 id="quick-tunnel-ohne-konto" tabindex="-1">Quick-Tunnel: ohne Konto <a class="header-anchor" href="#quick-tunnel-ohne-konto" aria-label="Permalink to &quot;Quick-Tunnel: ohne Konto&quot;">​</a></h3><p>Für den Kurs genügt der <strong>Quick-Tunnel</strong>. Er braucht weder ein Cloudflare-Konto noch eine eigene Domain:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloudflared</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080</span></span></code></pre></div><p>In der Ausgabe steht eine Adresse wie <code>https://&lt;zufall&gt;.trycloudflare.com</code>. Sie leitet auf den angegebenen Port. Das Programm bleibt im Vordergrund: Lass das Terminal offen, beende den Tunnel mit <code>Strg+C</code>.</p><p>Wichtig zu wissen (nach der Doku von Cloudflare):</p><ul><li>Die Adresse ist <strong>temporär</strong>. Sie funktioniert nur, solange <code>cloudflared</code> läuft, und ist bei <strong>jedem Start eine andere</strong>. Deshalb setzt das Mini-App-Beispiel die Menütaste bei jedem Start neu, und du setzt <code>MINI_APP_URL</code> jedes Mal neu.</li><li><strong>Jeder, der die Adresse kennt, erreicht deinen lokalen Dienst.</strong> Gib sie nicht weiter und lass den Tunnel nicht länger offen als nötig.</li><li>Quick-Tunnels sind für <strong>Tests und Entwicklung</strong> gedacht, nicht für den Betrieb. Es gibt keine Garantie für die Verfügbarkeit, höchstens 200 gleichzeitige Anfragen (weitere bekommen einen <code>429</code>) und keine Server-Sent Events.</li><li>Die Option <code>--allowed-mail</code> schützt eine Adresse mit einem Code per E-Mail. Sie verlangt eine Anmeldung im Browser und ist darum für Telegram <strong>nicht</strong> brauchbar: Die Server von Telegram, die einen Webhook aufrufen, können sich nicht per E-Mail anmelden.</li><li>Der Datenverkehr läuft über das Netz von Cloudflare. Schicke über den Tunnel nichts, was dort nicht durchlaufen soll.</li></ul><p>Für eine feste Adresse und den Dauerbetrieb gibt es den Cloudflare Tunnel mit Konto und Domain. Das ist nicht Teil dieses Kurses, die Doku erklärt es.</p><h3 id="installieren" tabindex="-1">Installieren <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installieren&quot;">​</a></h3><p>Die Downloadseite von Cloudflare führt alle Wege auf. Das Programm ist Open Source (Apache-2.0) und wird von Cloudflare auf GitHub gepflegt.</p><table tabindex="0"><thead><tr><th>System</th><th>Weg</th></tr></thead><tbody><tr><td><strong>Linux</strong></td><td>Paketquelle von Cloudflare (<a href="https://pkg.cloudflare.com/" target="_blank" rel="noreferrer">pkg.cloudflare.com</a>), oder <code>.deb</code>, <code>.rpm</code> oder eine einzelne Programmdatei von der GitHub-Releaseseite</td></tr><tr><td><strong>macOS</strong></td><td><code>brew install cloudflared</code>, oder ein Download von GitHub</td></tr><tr><td><strong>Windows</strong></td><td><code>.exe</code> oder <code>.msi</code> von der GitHub-Releaseseite. Unter Windows aktualisiert sich das Programm nicht selbst.</td></tr><tr><td><strong>Docker</strong></td><td>Image <code>cloudflare/cloudflared</code> auf Docker Hub</td></tr></tbody></table><p><strong>Ubuntu und Debian.</strong> Zwei Wege, beide mit <code>sudo</code>. Welche Ubuntu-Version du hast, zeigt <code>lsb_release -a</code>.</p><p><em>Weg 1: Paketquelle von Cloudflare (empfohlen).</em> Sie liefert auch spätere Aktualisierungen über <code>apt</code>. Die Befehle stammen von <a href="https://pkg.cloudflare.com/" target="_blank" rel="noreferrer">pkg.cloudflare.com</a>, Abschnitt „Any Debian Based Distribution&quot;. Sie gelten für Ubuntu 20.04, 22.04 und 24.04 gleichermaßen:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Schlüssel zum Prüfen der Pakete ablegen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode=0755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/keyrings</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pkg.cloudflare.com/cloudflare-main.gpg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/keyrings/cloudflare-main.gpg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Paketquelle (stabile Version) eintragen</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;deb [signed-by=/usr/share/keyrings/cloudflare-main.gpg] https://pkg.cloudflare.com/cloudflared any main&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/sources.list.d/cloudflared.list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># installieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflared</span></span></code></pre></div><p>Cloudflare hat Ende Oktober 2025 den Signaturschlüssel getauscht. Nimm deshalb immer die Befehle von der Seite von Cloudflare, wenn sich etwas an diesen Zeilen ändert. Später aktualisierst du mit <code>sudo apt-get update &amp;&amp; sudo apt-get install --only-upgrade cloudflared</code>.</p><p><em>Weg 2: einzelnes <code>.deb</code>-Paket von GitHub.</em> Das ist ein Download ohne Paketquelle, Aktualisierungen musst du selbst holen. Die Architektur zeigt <code>dpkg --print-architecture</code> (<code>amd64</code> oder <code>arm64</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># amd64 (die meisten PCs und Laptops)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflared.deb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64.deb</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># arm64 stattdessen:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># curl -fL -o cloudflared.deb https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-arm64.deb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflared.deb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflared.deb</span></span></code></pre></div><p>Unter Ubuntu in <strong>WSL</strong> gelten dieselben Befehle.</p><p>Prüfen, ob es installiert ist:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloudflared</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Unter WSL (Windows) installierst du die Linux-Version innerhalb von WSL, damit der Tunnel auf denselben <code>localhost</code> zeigt wie dein Java-Programm.</p><h3 id="so-benutzt-du-ihn-im-kurs" tabindex="-1">So benutzt du ihn im Kurs <a class="header-anchor" href="#so-benutzt-du-ihn-im-kurs" aria-label="Permalink to &quot;So benutzt du ihn im Kurs&quot;">​</a></h3><ol><li>In einem <strong>eigenen Terminal</strong> den Tunnel starten und die Adresse notieren:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloudflared</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080</span></span></code></pre></div></li><li>In einem <strong>zweiten Terminal</strong> das Beispiel mit dieser Adresse starten (zum Beispiel <code>MINI_APP_URL</code> in Lektion 11 oder <code>WEBHOOK_URL</code> in Lektion 6).</li><li>Der Port hinter <code>--url</code> muss der Port sein, auf dem dein Java-Programm lauscht. Die Beispiele nutzen 8080. Änderst du ihn (Umgebungsvariable <code>PORT</code>), ändere ihn auch im Befehl.</li><li>Am Ende beide Programme mit <code>Strg+C</code> beenden.</li></ol><p>Zeigt der Browser oder Telegram einen Fehler (zum Beispiel <code>502</code>), läuft meist dein Java-Programm nicht oder auf einem anderen Port als dem im Befehl.</p><h3 id="alternativen" tabindex="-1">Alternativen <a class="header-anchor" href="#alternativen" aria-label="Permalink to &quot;Alternativen&quot;">​</a></h3><p>Andere Tunnel-Dienste wie ngrok erfüllen denselben Zweck. Sie sind hier nicht getestet. Mit einem eigenen Server und einem Reverse Proxy (zum Beispiel nginx oder Caddy) vor deinem Programm bekommst du eine feste Adresse, siehe <a href="/learn_telegram/lektionen/06-webhooks.html">Lektion 6</a>.</p><h3 id="herstellerseiten" tabindex="-1">Herstellerseiten <a class="header-anchor" href="#herstellerseiten" aria-label="Permalink to &quot;Herstellerseiten&quot;">​</a></h3><ul><li><a href="https://developers.cloudflare.com/tunnel/" target="_blank" rel="noreferrer">Cloudflare Tunnel (Dokumentation)</a>: Überblick und Funktionsweise</li><li><a href="https://developers.cloudflare.com/tunnel/get-started/quick-tunnels/" target="_blank" rel="noreferrer">Quick Tunnels</a>: der Weg ohne Konto, mit allen Einschränkungen</li><li><a href="https://developers.cloudflare.com/tunnel/downloads/" target="_blank" rel="noreferrer">Downloads für cloudflared</a>: alle Systeme</li><li><a href="https://github.com/cloudflare/cloudflared" target="_blank" rel="noreferrer">cloudflared auf GitHub</a>: Quellcode, Releases, Lizenz</li></ul>`,38)])])}const k=s(t,[["render",l]]);export{c as __pageData,k as default};
